files.content:
.swatch{
  display:inline-block;
  flex:none;
  width:var(--s-3);
  height:var(--s-3);
  border-radius:var(--r-xs);
  background:var(--sw, transparent);
  box-shadow:inset 0 0 0 var(--bw-1) var(--border-input);
  vertical-align:middle;
}
.swatch-tile{
  border:var(--bw-1) solid var(--obsidian-800);
  border-radius:var(--r-md);
  overflow:hidden;
  background:var(--obsidian-900);
}
.swatch-tile-fill{
  height:var(--s-24);
  background:var(--sw, transparent);
  box-shadow:inset 0 calc(-1 * var(--bw-1)) 0 var(--border-input);
}
.swatch-tile-meta{
  padding:var(--s-3) var(--s-4);
  display:flex;
  flex-direction:column;
  gap:var(--s-0-5);
}
.swatch-tile-name{
  font-weight:600;
  font-size:var(--t-small);
  color:var(--obsidian-100);
}
.swatch-tile-hex{
  font-family:var(--font-mono);
  font-size:var(--t-caption);
  color:var(--obsidian-200);
  letter-spacing:var(--tr-mono);
}
.swatch-tile-role{
  font-family:var(--font-mono);
  font-size:var(--t-micro);
  letter-spacing:var(--tr-mono);
  text-transform:uppercase;
  color:var(--obsidian-300);
  margin-top:var(--s-0-5);
}
.swatch-tile-radius .swatch-tile-fill{
  display:flex;
  align-items:center;
  justify-content:center;
  background:var(--obsidian-950);
}
.swatch-tile-shape{
  width:var(--s-24);
  height:calc(var(--s-24) * .6);
  border-radius:var(--sw-r, 0);
  background:var(--obsidian-800);
  box-shadow:inset 0 0 0 var(--bw-1) var(--obsidian-400);
}
.swatch-tile-icon .swatch-tile-fill{
  height:auto;
  display:flex;
  align-items:center;
  justify-content:center;
  gap:var(--s-5);
  padding:var(--s-5);
  background:var(--obsidian-950);
  color:var(--obsidian-100);
}
.swatch-tile-zoom{
  position:relative;
  flex:none;
  width:var(--s-16);
  height:var(--s-16);
  background-image:linear-gradient(var(--obsidian-700) var(--bw-1),transparent var(--bw-1)),linear-gradient(90deg,var(--obsidian-700) var(--bw-1),transparent var(--bw-1));
  background-size:calc(100% / 16) calc(100% / 16);
  box-shadow:inset calc(-1 * var(--bw-1)) calc(-1 * var(--bw-1)) 0 var(--obsidian-700);
}
.swatch-tile-zoom::after{
  content:"";
  position:absolute;
  inset:calc(100% / 16);
  border:var(--bw-1) dashed var(--obsidian-400);
  pointer-events:none;
}
.swatch-tile-zoom .swatch-tile-glyph{
  position:absolute;
  inset:0;
  width:100%;
  height:100%;
  color:var(--primary-300);
}
.swatch-tile-sizes{
  display:flex;
  flex-direction:column;
  align-items:center;
  gap:var(--s-3);
}
.swatch-tile-shadow .swatch-tile-fill{
  height:calc(var(--s-24) * 1.25);
  overflow:hidden;
  display:flex;
  align-items:center;
  justify-content:center;
  background:var(--obsidian-900);
}
.swatch-tile-surface{
  width:var(--s-24);
  height:calc(var(--s-24) * .5);
  border-radius:var(--r-md);
  background:var(--obsidian-850);
  box-shadow:var(--sw-sh, none);
}
.swatch-list{
  display:flex;
  flex-direction:column;
  gap:var(--s-3);
}
.swatch-tile-type{
  display:flex;
}
.swatch-tile-type .swatch-tile-fill{
  flex:1;
  min-width:0;
  height:auto;
  max-height:calc(var(--s-24) * 1.25);
  display:flex;
  align-items:center;
  overflow:hidden;
  padding:var(--s-5) 0 var(--s-5) var(--s-5);
  background:var(--obsidian-950);
  box-shadow:none;
}
.swatch-type-sample{
  margin:0;
  white-space:nowrap;
  color:var(--obsidian-100);
}
.swatch-tile-type .swatch-tile-meta{
  flex:none;
  width:calc(var(--s-24) * 2.25);
  justify-content:center;
  border-left:var(--bw-1) solid var(--border-input);
}
@media (max-width: 720px){
  .swatch-tile-type{
    flex-direction:column;
  }
  .swatch-tile-type .swatch-tile-meta{
    width:auto;
    border-left:0;
    border-top:var(--bw-1) solid var(--border-input);
  }
}
.swatch-tile-space{
  display:flex;
}
.swatch-tile-space .swatch-tile-fill{
  flex:1;
  min-width:0;
  height:auto;
  display:flex;
  align-items:center;
  padding:var(--s-3) var(--s-5);
  overflow:hidden;
  box-shadow:none;
  background-color:var(--obsidian-950);
  background-image:linear-gradient(90deg,var(--obsidian-800) var(--bw-1),transparent var(--bw-1));
  background-size:var(--s-1) 100%;
  background-position:var(--s-5) 0;
}
.swatch-space-bar{
  display:block;
  flex:none;
  width:var(--sw-s, 0);
  min-width:var(--bw-1);
  height:var(--s-4);
  background:var(--primary-500);
}
.swatch-tile-space .swatch-tile-meta{
  flex:none;
  width:calc(var(--s-24) * 2.25);
  flex-direction:row;
  align-items:baseline;
  gap:var(--s-4);
  border-left:var(--bw-1) solid var(--border-input);
}
@media (max-width: 720px){
  .swatch-tile-space .swatch-tile-meta{
    width:auto;
    flex:none;
  }
}
.swatch-grid{
  display:grid;
  grid-template-columns:repeat(auto-fill,minmax(190px,1fr));
  gap:var(--s-3);
}
.swatch-grid-4{
  display:flex;
  gap:var(--s-3);
  container-type:inline-size;
}
.swatch-grid-4 > .swatch-tile{
  flex:1 1 0;
  min-width:0;
}
@container (max-width: 900px){
  .swatch-grid-4 > .swatch-tile:nth-child(n+4){
    display:none;
  }
}
@container (max-width: 720px){
  .swatch-grid-4 > .swatch-tile:nth-child(n+3){
    display:none;
  }
}
@container (max-width: 480px){
  .swatch-grid-4 > .swatch-tile:nth-child(n+2){
    display:none;
  }
}
.swatch-tile-motion .swatch-tile-fill{
  height:auto;
  display:flex;
  justify-content:center;
  background:var(--obsidian-950);
  padding:var(--s-6) var(--s-5);
}
.swatch-tile-plot{
  position:relative;
  flex:1 1 auto;
  max-width:calc(var(--s-24) * 2);
  aspect-ratio:1;
  margin:0 calc(var(--s-6) + var(--s-3)) 0 var(--s-2);
}
.swatch-tile-plot svg{
  position:absolute;
  inset:0;
  width:100%;
  height:100%;
  overflow:visible;
}
.swatch-tile-axis{
  stroke:var(--obsidian-400);
  stroke-width:1;
  vector-effect:non-scaling-stroke;
}
.swatch-tile-guide{
  stroke:var(--obsidian-700);
  stroke-width:1;
  stroke-dasharray:2 3;
  vector-effect:non-scaling-stroke;
}
.swatch-tile-curve{
  fill:none;
  stroke:var(--primary-300);
  stroke-width:2;
  vector-effect:non-scaling-stroke;
}
.swatch-tile-tick{
  position:absolute;
  font-family:var(--font-mono);
  font-size:var(--t-micro);
  letter-spacing:var(--tr-mono);
  color:var(--obsidian-300);
  line-height:1;
}
.swatch-tile-time, .swatch-tile-pos{
  position:absolute;
  inset:0;
  pointer-events:none;
}
.swatch-tile-pos::after{
  content:"";
  position:absolute;
  left:0;
  bottom:0;
  width:var(--s-2);
  height:var(--s-2);
  margin:0 0 calc(var(--s-2) / -2) calc(var(--s-2) / -2);
  border-radius:var(--r-full);
  background:var(--primary-500);
}
.swatch-tile-level{
  position:absolute;
  inset:0 calc(-1 * (var(--s-5) + var(--s-3))) 0 0;
  pointer-events:none;
}
.swatch-tile-level::after{
  content:"";
  position:absolute;
  left:0;
  right:0;
  bottom:0;
  border-top:var(--bw-1) dashed var(--obsidian-400);
}
.swatch-tile-rail{
  position:absolute;
  top:calc(var(--s-3) / -2);
  bottom:calc(var(--s-3) / -2);
  right:calc(-1 * (var(--s-5) + var(--s-3)));
  width:var(--s-3);
  border-radius:var(--r-full);
  background:var(--obsidian-900);
}
.swatch-tile-rise{
  position:absolute;
  top:calc(var(--s-3) / 2);
  bottom:calc(var(--s-3) / 2);
  left:0;
  right:0;
}
.swatch-tile-ball{
  position:absolute;
  left:0;
  bottom:0;
  width:var(--s-3);
  height:var(--s-3);
  margin-bottom:calc(var(--s-3) / -2);
  border-radius:var(--r-full);
  background:var(--primary-500);
}
.swatch-tile-time, .swatch-tile-pos, .swatch-tile-level, .swatch-tile-rise{
  animation-duration:calc(var(--d, var(--d-base)) * 2.5);
  animation-iteration-count:3;
  animation-fill-mode:both;
}
.swatch-tile-time{
  animation-name:swatch-time;
  animation-timing-function:linear;
}
.swatch-tile-pos, .swatch-tile-level, .swatch-tile-rise{
  animation-name:swatch-rise;
  animation-timing-function:var(--e, var(--ease-linear));
}
@media (prefers-reduced-motion: reduce){
  .swatch-tile-time, .swatch-tile-pos, .swatch-tile-level, .swatch-tile-rise{
    animation:none;
  }
  .swatch-tile-time{
    transform:translateX(100%);
  }
  .swatch-tile-pos, .swatch-tile-level, .swatch-tile-rise{
    transform:translateY(-100%);
  }
}
.swatch-hex{
  width:calc(var(--s-3) * 0.866);
  border-radius:0;
  box-shadow:none;
  clip-path:polygon(50% 0,100% 25%,100% 75%,50% 100%,0 75%,0 25%);
}
